function drawOccupation33(ui){const g=ui._mapGeom,c=ui.q?.('worldCanvas');if(!g||!c)return;const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=ui.world,cols=NS.NATION_COLORS||[];ctx.save();for(const t of w.map.tiles||[]){if(t.v33OccupierId==null)continue;const col=cols[Number(t.v33OccupierId)%Math.max(1,cols.length)]||'#ffffff',x=ox+t.x*cell,y=oy+t.y*cell;ctx.globalAlpha=.30;ctx.fillStyle=col;ctx.fillRect(x+cell*.12,y+cell*.12,cell*.76,cell*.76);ctx.globalAlpha=.75;ctx.strokeStyle=col;ctx.lineWidth=Math.max(1,cell*.045);ctx.beginPath();ctx.moveTo(x+cell*.18,y+cell*.82);ctx.lineTo(x+cell*.82,y+cell*.18);ctx.moveTo(x+cell*.35,y+cell*.88);ctx.lineTo(x+cell*.88,y+cell*.35);ctx.stroke();}ctx.restore();}
if(NS.UI){const set33=NS.UI.prototype.setWorld,head33=NS.UI.prototype.renderHeader,content33=NS.UI.prototype.renderVillageContent,world33=NS.UI.prototype.renderWorld;NS.UI.prototype.setWorld=function(w){return set33.call(this,attach33(w));};NS.UI.prototype.renderHeader=function(){head33.call(this);document.title='Village Observer V0.33';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33</strong>';const st=this.q('runtimeStatus');if(st){const wars=activeWars33(this.world).length;st.textContent=`✓ V0.33 전쟁 V1 · 선전포고/침공/전투/Person 사상자/후퇴/점령/종전 · active wars ${wars}`;}};NS.UI.prototype.renderVillageContent=function(){content33.call(this);const v=this.world.selectedNation,root=this.q('villageContent');if(v&&root&&this.sub==='military'&&!root.querySelector('.v33-war'))root.insertAdjacentHTML('afterbegin',warPanel33(v,this.world));};NS.UI.prototype.renderWorld=function(){world33.call(this);drawOccupation33(this);};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33-war{margin:0 0 10px;padding:11px;border:1px solid rgba(130,170,210,.3);border-radius:12px;background:rgba(65,95,125,.07)}.v33-war.active{border-color:rgba(235,105,90,.5);background:rgba(145,55,45,.09)}.v33-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:8px}.v33-grid span{padding:6px 7px;border-radius:8px;background:rgba(255,255,255,.045);font-size:11px}@media(max-width:760px){.v33-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;document.head.appendChild(st);}
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33'))NS.PATCH_NOTES.unshift({version:'V0.33',date:'2026-09-28',title:'War V1',summary:'0.32에서 완성한 Person 기반 군사사회 위에 실제 전쟁 루프를 연결합니다. 전략적 선전포고, 적 영토 Formation 이동, 준비태세/지형 기반 전투, 실제 Person 전사·부상, 후퇴, 임시 점령, 전쟁 피로와 종전을 구현합니다.',sections:[['전쟁 상태·선전포고',['한 국가는 V1에서 동시에 하나의 전쟁만 수행합니다. 국경 접촉, 전략적 우려, 관계, 야전 준비태세, 식량, 상대 전력과 최근 교역 의존도를 저빈도로 평가해 전쟁을 결정합니다.','전쟁이 시작되면 양국 관계와 위협도가 전시 상태로 전환되고 Field Formation이 전쟁 전용 이동기로 바뀝니다.']],['침공·전투',['평시 Formation 이동기는 자국 영토 규칙을 그대로 유지하고, 전쟁 중인 Field Formation만 적국 영토를 통과할 수 있는 V0.33 전용 경로를 사용합니다.','전투력은 실제 병력 수, Training, Equipment, Supply, Morale/Readiness와 방어 지형·군사시설을 사용합니다.','수도에서는 기존 CORE_GARRISON이 실제 방어 병력으로 참가합니다.']],['Person 사상자·후퇴',['전투 사상자는 실제 Cohort의 Person ID에서 선택됩니다. 전사자는 실제 alive=false가 되어 인구에서 사라지고, 부상자는 현역 Cohort에서 빠져 45~120일 동안 회복합니다.','패배한 Field Formation은 자국 방향으로 후퇴합니다. V1에서는 포로와 항복 시스템을 아직 사용하지 않습니다.']],['임시 점령',['적 영토를 확보해도 ownerId는 바뀌지 않고 occupierId만 기록합니다. 점령지는 생산 채취량이 65%로 감소하고 점령된 보급거점은 기존 F Supply에도 불리하게 작용합니다.','자국 Formation이 다시 진입하거나 전쟁이 끝나면 점령 상태가 해제됩니다.']],['전쟁 피로·종전',['전쟁 기간, 전사·부상, 피점령지, 식량·Gold 압박, 전투 패배가 War Exhaustion에 반영됩니다.','최소 전쟁기간 이후 피로도가 충분히 높아지거나 야전 전력이 붕괴하면 휴전합니다. V1 종전 시 모든 점령지는 원소유국으로 반환됩니다.']],['V1 범위 제한',['영구 영토 할양, 배상금, 동맹, 참전 요청, 포로, 해전, 공성전, 봉쇄, 병종, 장군·전술, 무기 국제무역은 이번 버전에 포함하지 않습니다.']]]});
